    /**
     * Method to retrieve the GiftCard via GiftCardFetchOneSummary
     * @param 	summary GiftCardFetchOneSummary 
     * @return 	GiftCardFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public GiftCard getGiftCard( GiftCardFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "GiftCardFetchOneSummary arg cannot be null" );
    	
    	GiftCard entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a GiftCard
        	// --------------------------------------
        	CompletableFuture<GiftCard> futureEntity = queryGateway.query(new FindGiftCardQuery( new LoadGiftCardFilter( summary.getGiftCardId() ) ), ResponseTypes.instanceOf(GiftCard.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate GiftCard with id " + summary.getGiftCardId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


